struct RecentExecutionTrace {
    struct Entry {
        const LsxDecodedRegion* region = nullptr;
        std::uint64_t guest_pc = 0;
    };

    std::array<Entry, 16> ring{};
    std::uint32_t next_ticket = 0;
    volatile std::uint32_t published_ticket = 0;

    void Publish(const std::uint64_t guest_pc, const LsxDecodedRegion* region) noexcept {
        const std::uint32_t ticket = next_ticket++;
        ring[ticket % ring.size()] = {.region = region, .guest_pc = guest_pc};
        __atomic_store_n(&published_ticket, ticket + 1u, __ATOMIC_RELEASE);
    }

    [[nodiscard]] std::uint32_t Published() const noexcept {
        return __atomic_load_n(&published_ticket, __ATOMIC_ACQUIRE);
    }
};
