                   ir.operands[0].type == X86_OPERAND_TYPE_REGISTER &&
                   can_native_write_operand(ir.operands[0]) &&
                   can_native_read_operand(ir.operands[ir.operand_count == 3 ? 1 : 0]) &&
                   can_native_read_operand(ir.operands[ir.operand_count == 3 ? 2 : 1]);
        case X86_MNEMONIC_MUL:
        case X86_MNEMONIC_DIV:
        case X86_MNEMONIC_IDIV:
            return ir.operand_count >= 1 && can_native_read_operand(ir.operands[0]);
        case X86_MNEMONIC_BEXTR:
            return ir.operand_count >= 3 &&
                   ir.operands[0].type == X86_OPERAND_TYPE_REGISTER &&
                   (ir.operands[0].size == 32 || ir.operands[0].size == 64) &&
                   can_native_write_operand(ir.operands[0]) &&
                   can_native_read_operand(ir.operands[1]) &&
                   can_native_read_operand(ir.operands[2]);
        case X86_MNEMONIC_BLSI:
        case X86_MNEMONIC_BLSR:
            return ir.operand_count >= 2 &&
                   ir.operands[0].type == X86_OPERAND_TYPE_REGISTER &&
                   (ir.operands[0].size == 32 || ir.operands[0].size == 64) &&
                   can_native_write_operand(ir.operands[0]) &&
                   can_native_read_operand(ir.operands[1]);
        case X86_MNEMONIC_CBW:
        case X86_MNEMONIC_CWDE:
        case X86_MNEMONIC_CDQE:
        case X86_MNEMONIC_CWD:
        case X86_MNEMONIC_CDQ:
        case X86_MNEMONIC_CQO:
            return true;
        case X86_MNEMONIC_PUSH:
            return ir.operand_count >= 1 && can_native_read_operand(ir.operands[0]);
        case X86_MNEMONIC_POP:
            return ir.operand_count >= 1 && can_native_write_operand(ir.operands[0]);
        case X86_MNEMONIC_LEAVE:
            return ir.operand_count == 0;
        case X86_MNEMONIC_SHL:
        case X86_MNEMONIC_SHR:
        case X86_MNEMONIC_SAR:
        case X86_MNEMONIC_ROL:
        case X86_MNEMONIC_ROR:
            return ir.operand_count >= 2 &&
                   can_native_read_operand(ir.operands[0]) &&
                   can_native_write_operand(ir.operands[0]) &&
                   (ir.operands[1].type == X86_OPERAND_TYPE_REGISTER ||
                    ir.operands[1].type == X86_OPERAND_TYPE_IMMEDIATE) &&
                   can_native_read_operand(ir.operands[1]);
        case X86_MNEMONIC_SHLD:
