                                                 mnemonic == X86_MNEMONIC_MULPD ||
                                                 mnemonic == X86_MNEMONIC_DIVPD ||
                                                 mnemonic == X86_MNEMONIC_VADDPD ||
                                                 mnemonic == X86_MNEMONIC_VSUBPD ||
                                                 mnemonic == X86_MNEMONIC_VMULPD ||
                                                 mnemonic == X86_MNEMONIC_VDIVPD;
                        const std::uint8_t lhs_index = vex ? 1u : 0u;
