                                emit_unordered();
                                code->orr(out_b, out_b, temp0_b);
                                break;
                            case 0x9:
                                code->fcmgt(output, rhs, lhs);
                                emit_unordered();
                                code->orr(out_b, out_b, temp0_b);
                                break;
                            case 0xa:
                                code->fcmge(output, rhs, lhs);
                                emit_unordered();
                                code->orr(out_b, out_b, temp0_b);
                                break;
                            case 0xb:
                                code->eor(out_b, out_b, out_b);
                                break;
                            case 0xc:
