                            code->bhi(count_out_of_range);
                            if (!shift_left) {
                                code->neg(code->x10, code->x10);
                            }
                            code->dup(code->v2.d2, code->x10);
                            code->ushl(code->v0.d2, code->v0.d2, code->v2.d2);
                            if (source_width == 32) {
                                code->ushl(code->v1.d2, code->v1.d2, code->v2.d2);
                            }
