                        std::uint32_t rhs_width = 0;
                        emitted = emit_vector_load_pair(ir, ir.operands[1], code->q0,
                                                        code->q1, lhs_width) &&
                                  emit_vector_load_pair(ir, ir.operands[2], code->q2,
                                                        code->q3, rhs_width) &&
                                  lhs_width == 16 && rhs_width == 16;
