                        break;
                    case X86_MNEMONIC_MFENCE:
                        code->dmb(Xbyak_aarch64::SY);
                        break;
                    case X86_MNEMONIC_SFENCE:
                        code->dmb(Xbyak_aarch64::ST);
                        break;
                    case X86_MNEMONIC_CLFLUSH:
                    case X86_MNEMONIC_CLFLUSHOPT:
                        break;
