enum class PackedStringAggregation : std::uint8_t {
    EqualAny = 0,
    Ranges = 1,
    EqualEach = 2,
    EqualOrdered = 3,
};

enum class PackedStringPolarity : std::uint8_t {
    Positive = 0,
    Negative = 1,
    PositiveMasked = 2,
    NegativeMasked = 3,
};

std::int32_t PackedStringElement(const std::uint8_t* vector, const std::int32_t index,
                                 const std::uint8_t control) {
    switch (control & 0x3u) {
    case 0:
        return vector[index];
    case 1:
        return LoadUnaligned<std::uint16_t>(vector + (index * 2));
    case 2:
        return static_cast<std::int8_t>(vector[index]);
    case 3:
    default:
        return LoadUnaligned<std::int16_t>(vector + (index * 2));
    }
}

std::int32_t PackedStringImplicitLength(const std::uint8_t* vector,
                                        const std::uint8_t control) {
    const bool words = (control & 1u) != 0;
    const std::int32_t element_count = words ? 8 : 16;
    for (std::int32_t i = 0; i < element_count; ++i) {
        const bool is_zero = words ? LoadUnaligned<std::uint16_t>(vector + (i * 2)) == 0
                                   : vector[i] == 0;
        if (is_zero) {
            return i;
        }
    }
    return element_count;
}

std::int32_t PackedStringExplicitLength(const std::uint64_t raw_length,
                                        const bool rex_w,
                                        const std::uint8_t control) {
    const std::int64_t signed_length =
        rex_w ? static_cast<std::int64_t>(raw_length)
              : static_cast<std::int32_t>(raw_length);
    const std::int64_t limit = (control & 1u) != 0 ? 8 : 16;
    if (signed_length < -limit || signed_length > limit) {
        return static_cast<std::int32_t>(limit);
    }
    return static_cast<std::int32_t>(signed_length < 0 ? -signed_length : signed_length);
}

std::uint32_t PackedStringEqualAny(const std::uint8_t* lhs, const std::int32_t valid_lhs,
                                   const std::uint8_t* rhs, const std::int32_t valid_rhs,
                                   const std::uint8_t control) {
    std::uint32_t result = 0;
    for (std::int32_t j = valid_rhs; j >= 0; --j) {
        result <<= 1;
        const std::int32_t rhs_value = PackedStringElement(rhs, j, control);
        for (std::int32_t i = valid_lhs; i >= 0; --i) {
            result |= static_cast<std::uint32_t>(
                rhs_value == PackedStringElement(lhs, i, control));
        }
    }
    return result;
}

std::uint32_t PackedStringRanges(const std::uint8_t* lhs, const std::int32_t valid_lhs,
                                 const std::uint8_t* rhs, const std::int32_t valid_rhs,
                                 const std::uint8_t control) {
    std::uint32_t result = 0;
    for (std::int32_t j = valid_rhs; j >= 0; --j) {
        result <<= 1;
        const std::int32_t element = PackedStringElement(rhs, j, control);
        for (std::int32_t i = (valid_lhs - 1) | 1; i >= 0; i -= 2) {
            const std::int32_t upper = PackedStringElement(lhs, i, control);
            const std::int32_t lower = PackedStringElement(lhs, i - 1, control);
            result |= static_cast<std::uint32_t>(upper >= element && lower <= element);
        }
    }
    return result;
}

std::uint32_t PackedStringEqualEach(const std::uint8_t* lhs,
                                    const std::int32_t valid_lhs,
                                    const std::uint8_t* rhs,
                                    const std::int32_t valid_rhs,
                                    const std::uint8_t control) {
    const std::int32_t upper_limit = (16 >> (control & 1u)) - 1;
    const std::int32_t max_valid = std::max(valid_lhs, valid_rhs);
    const std::int32_t min_valid = std::min(valid_lhs, valid_rhs);

    std::uint32_t result = (1u << (upper_limit - max_valid)) - 1u;
    result <<= max_valid - min_valid;
    for (std::int32_t i = min_valid; i >= 0; --i) {
        result <<= 1;
        result |= static_cast<std::uint32_t>(
            PackedStringElement(lhs, i, control) == PackedStringElement(rhs, i, control));
    }
    return result;
}

std::uint32_t PackedStringEqualOrdered(const std::uint8_t* lhs,
                                       const std::int32_t valid_lhs,
                                       const std::uint8_t* rhs,
                                       const std::int32_t valid_rhs,
                                       const std::uint8_t control) {
    const std::int32_t upper_limit = (16 >> (control & 1u)) - 1;
    if (valid_lhs == -1) {
        return (2u << upper_limit) - 1u;
    }

    std::uint32_t result = 0;
    const std::int32_t initial =
        valid_rhs == upper_limit ? valid_rhs : valid_rhs - valid_lhs;
    for (std::int32_t j = initial; j >= 0; --j) {
        result <<= 1;
        std::uint32_t value = 1;
        const std::int32_t start = std::min(valid_rhs - j, valid_lhs);
        for (std::int32_t i = start; i >= 0; --i) {
            value &= static_cast<std::uint32_t>(
                PackedStringElement(lhs, i, control) ==
                PackedStringElement(rhs, i + j, control));
        }
        result |= value;
    }
    return result;
}

std::uint32_t PackedStringCompareMask(const std::uint8_t* lhs,
                                      const std::int32_t lhs_length,
                                      const std::uint8_t* rhs,
                                      const std::int32_t rhs_length,
                                      const std::uint8_t control) {
    const std::int32_t valid_lhs = lhs_length - 1;
    const std::int32_t valid_rhs = rhs_length - 1;
    std::uint32_t result = 0;
    switch (static_cast<PackedStringAggregation>((control >> 2) & 0x3u)) {
    case PackedStringAggregation::EqualAny:
        result = PackedStringEqualAny(lhs, valid_lhs, rhs, valid_rhs, control);
        break;
    case PackedStringAggregation::Ranges:
        result = PackedStringRanges(lhs, valid_lhs, rhs, valid_rhs, control);
        break;
    case PackedStringAggregation::EqualEach:
        result = PackedStringEqualEach(lhs, valid_lhs, rhs, valid_rhs, control);
        break;
    case PackedStringAggregation::EqualOrdered:
        result = PackedStringEqualOrdered(lhs, valid_lhs, rhs, valid_rhs, control);
        break;
    }

    const std::int32_t element_count = 16 >> (control & 1u);
    const std::uint32_t full_mask = (1u << element_count) - 1u;
    switch (static_cast<PackedStringPolarity>((control >> 4) & 0x3u)) {
    case PackedStringPolarity::Negative:
        result ^= full_mask;
        break;
    case PackedStringPolarity::NegativeMasked:
        result ^= (1u << rhs_length) - 1u;
        break;
    case PackedStringPolarity::Positive:
    case PackedStringPolarity::PositiveMasked:
        break;
    }
    return result & full_mask;
}

void SetPackedStringCompareFlags(LsxMachineImage& state, const std::uint32_t result,
                                 const std::int32_t lhs_length,
                                 const std::int32_t rhs_length,
                                 const std::int32_t element_count) {
    std::uint64_t flags = 0;
    if (result != 0) {
        flags |= kFlagCf;
    }
    if (rhs_length < element_count) {
        flags |= kFlagZf;
    }
    if (lhs_length < element_count) {
        flags |= kFlagSf;
    }
    if ((result & 1u) != 0) {
        flags |= kFlagOf;
    }
    StoreStatusFlags(state, flags);
}

bool ExecutePackedStringCompare(LsxMachineImage& state, const LsxDecodedOp& ir) {
    const auto mnemonic = static_cast<X86Mnemonic>(ir.mnemonic);
    std::array<std::uint8_t, kXmmRegisterBytes> lhs{};
    std::array<std::uint8_t, kXmmRegisterBytes> rhs{};
    if (!ReadVector128(state, ir.decoded, ir.operands[0], lhs) ||
        !ReadVector128(state, ir.decoded, ir.operands[1], rhs)) {
        return false;
    }

    const std::uint8_t control = static_cast<std::uint8_t>(ir.operands[2].imm.value.u);
    const std::int32_t element_count = 16 >> (control & 1u);
    std::int32_t lhs_length = 0;
    std::int32_t rhs_length = 0;
    if (IsExplicitLengthPackedStringCompare(mnemonic)) {
        const bool rex_w = ir.decoded.operand_width == 64;
        lhs_length = PackedStringExplicitLength(ReadGuestGpr64(state, LsxGpr::Rax), rex_w,
                                                control);
        rhs_length = PackedStringExplicitLength(ReadGuestGpr64(state, LsxGpr::Rdx), rex_w,
                                                control);
    } else {
        lhs_length = PackedStringImplicitLength(lhs.data(), control);
        rhs_length = PackedStringImplicitLength(rhs.data(), control);
    }

    const std::uint32_t result =
        PackedStringCompareMask(lhs.data(), lhs_length, rhs.data(), rhs_length, control);
    if (IsMaskPackedStringCompare(mnemonic)) {
        auto* xmm0 = XmmLane(state, 0);
        if (xmm0 == nullptr) {
            return false;
        }
        std::array<std::uint8_t, 16> mask{};
        if ((control & 0x40u) != 0) {
            if ((control & 1u) != 0) {
                for (std::size_t i = 0; i < 8; ++i) {
                    StoreUnaligned<std::uint16_t>(mask.data() + (i * 2),
                                                  (result & (1u << i)) != 0 ? 0xffffu : 0u);
                }
            } else {
                for (std::size_t i = 0; i < 16; ++i) {
                    mask[i] = (result & (1u << i)) != 0 ? 0xffu : 0u;
                }
            }
        } else {
            StoreUnaligned<std::uint16_t>(mask.data(), static_cast<std::uint16_t>(result));
        }
        std::memcpy(xmm0, mask.data(), mask.size());
        if (VectorWriteZerosUpper(ir.decoded)) {
            std::memset(xmm0 + 16, 0, 16);
        }
    } else {
        std::uint32_t index = static_cast<std::uint32_t>(element_count);
        if (result != 0) {
            index = (control & 0x40u) != 0
                        ? 31u - static_cast<std::uint32_t>(std::countl_zero(result))
                        : static_cast<std::uint32_t>(std::countr_zero(result));
        }
        WriteGuestGpr32(state, LsxGpr::Rcx, index);
    }

    SetPackedStringCompareFlags(state, result, lhs_length, rhs_length, element_count);
    return true;
}

