    case X86_MNEMONIC_FLD1:
    case X86_MNEMONIC_FLDL2E:
    case X86_MNEMONIC_FLDL2T:
    case X86_MNEMONIC_FLDLG2:
    case X86_MNEMONIC_FLDLN2:
    case X86_MNEMONIC_FLDPI:
    case X86_MNEMONIC_FLDZ:
