namespace {
struct AccumulatorProduct {
    std::uint64_t lower_half{};
    std::uint64_t upper_half{};
    bool does_not_fit{};
};

std::int64_t SignExtendOperand(const std::uint64_t value, const std::uint32_t width) {
    if (width == 64) {
        return std::bit_cast<std::int64_t>(value);
    }
    const auto shift = 64u - width;
    return static_cast<std::int64_t>(value << shift) >> shift;
}

AccumulatorProduct FormAccumulatorProduct(const std::uint64_t lhs, const std::uint64_t rhs,
                                          const std::uint32_t width, const bool signed_inputs) {
    const auto lane_mask = TruncateToOperandWidth(UINT64_MAX, width);
    __uint128_t product_bits = 0;
    bool overflow = false;
    if (signed_inputs) {
        const __int128 product = static_cast<__int128>(SignExtendOperand(lhs & lane_mask, width)) *
                                 SignExtendOperand(rhs & lane_mask, width);
        product_bits = static_cast<__uint128_t>(product);
        const __int128 minimum = -(static_cast<__int128>(1) << (width - 1u));
        const __int128 maximum = (static_cast<__int128>(1) << (width - 1u)) - 1;
        overflow = product < minimum || product > maximum;
    } else {
        product_bits = static_cast<__uint128_t>(lhs & lane_mask) * (rhs & lane_mask);
        overflow = (product_bits >> width) != 0;
    }
    return {static_cast<std::uint64_t>(product_bits) & lane_mask,
            static_cast<std::uint64_t>(product_bits >> width) & lane_mask, overflow};
}

void CommitAccumulatorProduct(LsxMachineImage& state, const AccumulatorProduct& product,
                              const std::uint32_t width) {
    if (width == 8) {
        const auto packed_ax = product.lower_half | (product.upper_half << 8u);
        WriteGuestGpr16(state, LsxGpr::Rax, static_cast<std::uint16_t>(packed_ax));
        return;
    }
    if (width == 16) {
        WriteGuestGpr16(state, LsxGpr::Rax, static_cast<std::uint16_t>(product.lower_half));
        WriteGuestGpr16(state, LsxGpr::Rdx, static_cast<std::uint16_t>(product.upper_half));
    } else if (width == 32) {
        WriteGuestGpr32(state, LsxGpr::Rax, static_cast<std::uint32_t>(product.lower_half));
        WriteGuestGpr32(state, LsxGpr::Rdx, static_cast<std::uint32_t>(product.upper_half));
    } else {
        WriteGuestGpr64(state, LsxGpr::Rax, product.lower_half);
        WriteGuestGpr64(state, LsxGpr::Rdx, product.upper_half);
    }
}
}

[[gnu::always_inline]] static inline void SemanticKernelMultiplyAccumulatorPair(LsxMachineImage& state, const std::uint64_t operand,
                             const std::uint32_t size_bits, const bool is_signed){
    if (size_bits != 8 && size_bits != 16 && size_bits != 32 && size_bits != 64) {
        return;
    }
    const auto product = FormAccumulatorProduct(ReadGuestGpr64(state, LsxGpr::Rax), operand,
                                                size_bits, is_signed);
    CommitAccumulatorProduct(state, product, size_bits);
    const auto arithmetic_flags = product.does_not_fit ? kFlagCf | kFlagOf : UINT64_C(0);
    state.rflags = (state.rflags & ~(kFlagCf | kFlagOf)) | arithmetic_flags;
}

void MultiplyAccumulatorPair(LsxMachineImage& argument0, const std::uint64_t argument1, const std::uint32_t argument2, const bool argument3) {
    SemanticKernelMultiplyAccumulatorPair(argument0, argument1, argument2, argument3);
}

[[gnu::always_inline]] static inline void SemanticKernelDivideAccumulatorPair(LsxMachineImage& state, const std::uint64_t divisor, const std::uint32_t size_bits,
            const bool is_signed){
    const auto divide_error = [] {
#ifdef __ANDROID__
        (void)executor_jit_defer_synchronous_guest_fault(
            SIGFPE, FPE_INTDIV, 0, 0, 0, 0, 0);
#endif
    };

    switch (size_bits) {
    case 8: {
        const std::uint64_t rax = ReadGuestGpr64(state, LsxGpr::Rax);
        if (is_signed) {
            const std::int32_t dividend = static_cast<std::int16_t>(rax & 0xffffu);
            const std::int32_t rhs = static_cast<std::int8_t>(divisor & 0xffu);
            if (rhs == 0) {
                divide_error();
                return;
            }
            const std::int32_t quotient = dividend / rhs;
            if (quotient < INT8_MIN || quotient > INT8_MAX) {
                divide_error();
                return;
            }
            const std::int32_t remainder = dividend % rhs;
            WriteGuestGpr16(state, LsxGpr::Rax,
                     static_cast<std::uint16_t>(static_cast<std::uint8_t>(quotient)) |
                         (static_cast<std::uint16_t>(static_cast<std::uint8_t>(remainder)) << 8u));
        } else {
            const std::uint32_t dividend = static_cast<std::uint16_t>(rax & 0xffffu);
            const std::uint32_t rhs = static_cast<std::uint8_t>(divisor & 0xffu);
            if (rhs == 0) {
                divide_error();
                return;
            }
            const std::uint32_t quotient = dividend / rhs;
            if (quotient > UINT8_MAX) {
                divide_error();
                return;
            }
            const std::uint32_t remainder = dividend % rhs;
            WriteGuestGpr16(state, LsxGpr::Rax,
                     static_cast<std::uint16_t>(quotient | (remainder << 8u)));
        }
        break;
    }
    case 16: {
        const std::uint32_t dividend = (static_cast<std::uint32_t>(ReadGuestGpr16(state, LsxGpr::Rdx)) << 16) |
                                       ReadGuestGpr16(state, LsxGpr::Rax);
        if (is_signed) {
            const std::int64_t signed_dividend = static_cast<std::int32_t>(dividend);
            const std::int64_t rhs = static_cast<std::int16_t>(divisor & 0xffffu);
            if (rhs == 0) {
                divide_error();
                return;
            }
            const std::int64_t quotient = signed_dividend / rhs;
            if (quotient < INT16_MIN || quotient > INT16_MAX) {
                divide_error();
                return;
            }
            WriteGuestGpr16(state, LsxGpr::Rax, static_cast<std::uint16_t>(quotient));
            WriteGuestGpr16(state, LsxGpr::Rdx,
                     static_cast<std::uint16_t>(signed_dividend % rhs));
        } else {
            const std::uint32_t rhs = static_cast<std::uint16_t>(divisor & 0xffffu);
            if (rhs == 0) {
                divide_error();
                return;
            }
            const std::uint32_t quotient = dividend / rhs;
            if (quotient > UINT16_MAX) {
                divide_error();
                return;
            }
            WriteGuestGpr16(state, LsxGpr::Rax, static_cast<std::uint16_t>(quotient));
            WriteGuestGpr16(state, LsxGpr::Rdx, static_cast<std::uint16_t>(dividend % rhs));
        }
        break;
    }
    case 32: {
        const std::uint64_t dividend = (static_cast<std::uint64_t>(ReadGuestGpr32(state, LsxGpr::Rdx)) << 32) |
                                       ReadGuestGpr32(state, LsxGpr::Rax);
        if (is_signed) {
            const __int128_t signed_dividend = static_cast<std::int64_t>(dividend);
            const __int128_t rhs = static_cast<std::int32_t>(divisor & 0xffffffffu);
            if (rhs == 0) {
                divide_error();
                return;
            }
            const __int128_t quotient = signed_dividend / rhs;
            if (quotient < INT32_MIN || quotient > INT32_MAX) {
                divide_error();
                return;
            }
            WriteGuestGpr32(state, LsxGpr::Rax, static_cast<std::uint32_t>(quotient));
            WriteGuestGpr32(state, LsxGpr::Rdx,
                     static_cast<std::uint32_t>(signed_dividend % rhs));
        } else {
            const std::uint64_t rhs = static_cast<std::uint32_t>(divisor & 0xffffffffu);
            if (rhs == 0) {
                divide_error();
                return;
            }
            const std::uint64_t quotient = dividend / rhs;
            if (quotient > UINT32_MAX) {
                divide_error();
                return;
            }
            WriteGuestGpr32(state, LsxGpr::Rax, static_cast<std::uint32_t>(quotient));
            WriteGuestGpr32(state, LsxGpr::Rdx, static_cast<std::uint32_t>(dividend % rhs));
        }
        break;
    }
    case 64: {
        if (is_signed) {
            const std::uint64_t low = ReadGuestGpr64(state, LsxGpr::Rax);
            const std::int64_t high = static_cast<std::int64_t>(ReadGuestGpr64(state, LsxGpr::Rdx));
            const std::int64_t divisor64 = static_cast<std::int64_t>(divisor);
            const __int128_t rhs = divisor64;
            if (rhs == 0) {
                divide_error();
                return;
            }
            if (high == INT64_MIN && low == 0 && divisor64 == -1) {
                divide_error();
                return;
            }
            const __int128_t dividend =
                static_cast<__int128_t>(high) *
                    (static_cast<__int128_t>(1) << 64u) +
                static_cast<__int128_t>(low);
            const __int128_t quotient = dividend / rhs;
            if (quotient < static_cast<__int128_t>(INT64_MIN) ||
                quotient > static_cast<__int128_t>(INT64_MAX)) {
                divide_error();
                return;
            }
            WriteGuestGpr64(state, LsxGpr::Rax, static_cast<std::uint64_t>(quotient));
            WriteGuestGpr64(state, LsxGpr::Rdx,
                     static_cast<std::uint64_t>(dividend % rhs));
        } else {
            const auto dividend = (static_cast<__uint128_t>(ReadGuestGpr64(state, LsxGpr::Rdx)) << 64) |
                                  static_cast<__uint128_t>(ReadGuestGpr64(state, LsxGpr::Rax));
            const auto rhs = static_cast<__uint128_t>(divisor);
            if (rhs == 0) {
                divide_error();
                return;
            }
            const __uint128_t quotient = dividend / rhs;
            if (quotient > UINT64_MAX) {
                divide_error();
                return;
            }
            WriteGuestGpr64(state, LsxGpr::Rax, static_cast<std::uint64_t>(quotient));
            WriteGuestGpr64(state, LsxGpr::Rdx, static_cast<std::uint64_t>(dividend % rhs));
        }
        break;
    }
    default:
        break;
    }
}

void DivideAccumulatorPair(LsxMachineImage& argument0, const std::uint64_t argument1, const std::uint32_t argument2, const bool argument3) {
    SemanticKernelDivideAccumulatorPair(argument0, argument1, argument2, argument3);
}

namespace {
struct CarryArithmeticResult {
    std::uint64_t left{};
    std::uint64_t right{};
    std::uint64_t value{};
    bool incoming_carry{};
};

CarryArithmeticResult EvaluateCarryArithmetic(const std::uint64_t left,
                                              const std::uint64_t right,
                                              const std::uint32_t width,
                                              const bool subtract,
                                              const bool incoming_carry) {
    const auto width_mask = TruncateToOperandWidth(UINT64_MAX, width);
    CarryArithmeticResult evaluated{left & width_mask, right & width_mask, 0,
                                    incoming_carry};
    const std::uint64_t carry_value = static_cast<std::uint64_t>(incoming_carry);
    evaluated.value = TruncateToOperandWidth(
        subtract ? evaluated.left - evaluated.right - carry_value
                 : evaluated.left + evaluated.right + carry_value,
        width);
    return evaluated;
}

void PublishCarryArithmetic(LsxMachineImage& state, const CarryArithmeticResult& evaluated,
                            const bool subtract, const std::uint32_t width) {
    if (subtract) {
        RecordBorrowingSubtractionFlags(state, evaluated.left, evaluated.right,
                                        evaluated.incoming_carry, evaluated.value, width);
        return;
    }
    RecordCarryingAdditionFlags(state, evaluated.left, evaluated.right,
                                evaluated.incoming_carry, evaluated.value, width);
}
}

[[gnu::always_inline]] static inline void SemanticKernelExecuteCarryArithmetic(
    LsxMachineImage& state, const std::size_t state_offset, const std::uint64_t operand,
    const bool subtract, const std::uint32_t size_bits) {
    const auto evaluated = EvaluateCarryArithmetic(
        LoadStateLane(state, state_offset), operand, size_bits, subtract,
        (state.rflags & kFlagCf) != 0);
    PublishCarryArithmetic(state, evaluated, subtract, size_bits);
    StoreStateLane(state, state_offset, evaluated.value, size_bits);
}

