namespace {

bool TryGetStringSpan(const std::uint64_t cursor, const std::uint64_t element_size,
                      const std::uint64_t count, const bool backward, std::uint64_t& span_begin,
                      std::size_t& span_size) {
    if (element_size == 0 || element_size > sizeof(std::uint64_t) || count == 0 ||
        count > std::numeric_limits<std::size_t>::max() / element_size) {
        return false;
    }
    const std::size_t bytes = static_cast<std::size_t>(count * element_size);
    if (bytes == 0 || cursor > ~std::uint64_t{0} - (element_size - 1)) {
        return false;
    }
    if (backward) {
        const std::uint64_t rewind = static_cast<std::uint64_t>(bytes - element_size);
        if (cursor < rewind) {
            return false;
        }
        span_begin = cursor - rewind;
    } else {
        if (cursor > ~std::uint64_t{0} - static_cast<std::uint64_t>(bytes - 1)) {
            return false;
        }
        span_begin = cursor;
    }
    span_size = bytes;
    return true;
}

bool StringSpansOverlap(const std::uint64_t lhs, const std::uint64_t rhs,
                        const std::size_t bytes) {
    const std::uint64_t lhs_last = lhs + static_cast<std::uint64_t>(bytes - 1);
    const std::uint64_t rhs_last = rhs + static_cast<std::uint64_t>(bytes - 1);
    return lhs <= rhs_last && rhs <= lhs_last;
}

bool TryBulkMovs(const std::uint64_t rsi, const std::uint64_t rdi,
                 const std::uint64_t element_size, const std::uint64_t count,
                 const bool backward) {
    if (count < 4) {
        return false;
    }
    std::uint64_t source_begin = 0;
    std::uint64_t destination_begin = 0;
    std::size_t source_bytes = 0;
    std::size_t destination_bytes = 0;
    if (!TryGetStringSpan(rsi, element_size, count, backward, source_begin, source_bytes) ||
        !TryGetStringSpan(rdi, element_size, count, backward, destination_begin,
                          destination_bytes) ||
        source_bytes != destination_bytes ||
        StringSpansOverlap(source_begin, destination_begin, source_bytes)) {
        return false;
    }
    if (!ExecutorJitIsReadableGuestRange(source_begin, source_bytes) ||
        !ExecutorJitIsReadableGuestRange(destination_begin, destination_bytes)) {
        return false;
    }
    if (!ExecutorJitWriteGuestBytes(destination_begin,
                                         reinterpret_cast<const void*>(source_begin),
                                         source_bytes)) {
        return false;
    }
    g_jit_rep_movs_bulk_calls.fetch_add(1, std::memory_order_relaxed);
    g_jit_rep_movs_bulk_bytes.fetch_add(source_bytes, std::memory_order_relaxed);
    return true;
}

bool TryBulkStos(const std::uint64_t rdi, const std::uint64_t rax,
                 const std::uint64_t element_size, const std::uint64_t count,
                 const bool backward) {
    if (count < 4) {
        return false;
    }
    std::uint64_t destination_begin = 0;
    std::size_t destination_bytes = 0;
    if (!TryGetStringSpan(rdi, element_size, count, backward, destination_begin,
                          destination_bytes) ||
        !ExecutorJitIsReadableGuestRange(destination_begin, destination_bytes)) {
        return false;
    }

    std::uint64_t repeated_lane = rax;
    switch (element_size) {
    case 1:
        repeated_lane = (rax & 0xffu) * 0x0101010101010101ull;
        break;
    case 2:
        repeated_lane = (rax & 0xffffu) * 0x0001000100010001ull;
        break;
    case 4:
        repeated_lane = (rax & 0xffffffffu) |
                        ((rax & 0xffffffffu) << 32u);
        break;
    case 8:
        break;
    default:
        return false;
    }
    if (destination_bytes <= sizeof(repeated_lane)) {
        if (!ExecutorJitWriteGuestBytes(destination_begin, &repeated_lane,
                                        destination_bytes)) {
            return false;
        }
        g_jit_rep_stos_bulk_calls.fetch_add(1, std::memory_order_relaxed);
        g_jit_rep_stos_bulk_bytes.fetch_add(destination_bytes,
                                             std::memory_order_relaxed);
        return true;
    }

    constexpr std::size_t kFillChunkBytes = 16 * 1024;
    alignas(64) std::array<std::uint8_t, kFillChunkBytes> pattern;
    const std::size_t useful_pattern_bytes =
        std::min(pattern.size(), destination_bytes);
    std::memcpy(pattern.data(), &repeated_lane,
                std::min(sizeof(repeated_lane), useful_pattern_bytes));
    std::size_t pattern_bytes =
        std::min(sizeof(repeated_lane), useful_pattern_bytes);
    while (pattern_bytes < useful_pattern_bytes) {
        const std::size_t copy_bytes =
            std::min(pattern_bytes, useful_pattern_bytes - pattern_bytes);
        std::memcpy(pattern.data() + pattern_bytes, pattern.data(), copy_bytes);
        pattern_bytes += copy_bytes;
    }

    std::size_t offset = 0;
    while (offset < destination_bytes) {
        const std::size_t chunk =
            std::min(useful_pattern_bytes, destination_bytes - offset);
        if (!ExecutorJitWriteGuestBytes(destination_begin + offset, pattern.data(), chunk)) {
            ThrowInvalidGuestMemoryAccess("write", destination_begin + offset,
                                          static_cast<std::uint32_t>(chunk));
        }
        offset += chunk;
    }
    g_jit_rep_stos_bulk_calls.fetch_add(1, std::memory_order_relaxed);
    g_jit_rep_stos_bulk_bytes.fetch_add(destination_bytes, std::memory_order_relaxed);
    return true;
}

}

namespace {
enum class StringTransferKind : std::uint8_t { Copy, Fill };

void ExecuteStringTransfer(LsxMachineImage& state, const std::uint64_t element_bytes,
                           const bool repeats, const StringTransferKind kind) {
    if (element_bytes == 0 || element_bytes > sizeof(std::uint64_t)) {
        return;
    }
    const auto iterations = repeats ? ReadGuestGpr64(state, LsxGpr::Rcx) : UINT64_C(1);
    if (iterations == 0) {
        return;
    }
    std::array<std::uint64_t, 2> cursor{
        ReadGuestGpr64(state, LsxGpr::Rsi), ReadGuestGpr64(state, LsxGpr::Rdi)};
    const bool descending = (state.rflags & kFlagDf) != 0;
    const auto accumulator = ReadGuestGpr64(state, LsxGpr::Rax);
    const bool bulk_completed = repeats &&
        (kind == StringTransferKind::Copy
             ? TryBulkMovs(cursor[0], cursor[1], element_bytes, iterations, descending)
             : TryBulkStos(cursor[1], accumulator, element_bytes, iterations, descending));
    const auto step = descending ? std::uint64_t{0} - element_bytes : element_bytes;
    if (!bulk_completed) {
        std::array<std::uint8_t, sizeof(std::uint64_t)> element{};
        for (std::uint64_t iteration = 0; iteration != iterations; ++iteration) {
            const void* payload = &accumulator;
            if (kind == StringTransferKind::Copy) {
                CopyBytesFromGuest(cursor[0], element.data(), static_cast<std::uint32_t>(element_bytes));
                payload = element.data();
                cursor[0] += step;
            }
            CopyBytesToGuest(cursor[1], payload, static_cast<std::uint32_t>(element_bytes));
            cursor[1] += step;
        }
    } else {
        const auto displacement = step * iterations;
        cursor[1] += displacement;
        if (kind == StringTransferKind::Copy) {
            cursor[0] += displacement;
        }
    }
    if (kind == StringTransferKind::Copy) {
        WriteGuestGpr64(state, LsxGpr::Rsi, cursor[0]);
    }
    WriteGuestGpr64(state, LsxGpr::Rdi, cursor[1]);
    if (repeats) {
        WriteGuestGpr64(state, LsxGpr::Rcx, 0);
    }
}
}

