namespace {
template <typename Float, typename Bits>
void StoreScalarMinMax(void* dst, const void* lhs_ptr, const void* rhs_ptr,
                       const ScalarArithOp op) {
    const Bits lhs_bits = LoadUnaligned<Bits>(lhs_ptr);
    const Bits rhs_bits = LoadUnaligned<Bits>(rhs_ptr);
    Float lhs{};
    Float rhs{};
    std::memcpy(&lhs, &lhs_bits, sizeof(lhs));
    std::memcpy(&rhs, &rhs_bits, sizeof(rhs));
    const bool unordered = std::isnan(lhs) || std::isnan(rhs);
    const bool select_lhs = !unordered &&
        (op == ScalarArithOp::Minimum ? lhs < rhs : lhs > rhs);
    StoreUnaligned<Bits>(dst, select_lhs ? lhs_bits : rhs_bits);
}

double ApplyScalarRound(const double value, const std::uint32_t mode) {
    return Lsx4::Translation::RoundFloatingValue(value, mode);
}
}

namespace {
template <typename Float, typename Bits>
void EvaluateScalarFloatingLane(SemanticVectorImage& output, const void* left_source,
                                const void* right_source, const ScalarArithOp operation) {
    const bool selects_operand = operation == ScalarArithOp::Minimum ||
                                 operation == ScalarArithOp::Maximum;
    if (selects_operand) {
        StoreScalarMinMax<Float, Bits>(output.bytes.data(), left_source, right_source, operation);
        return;
    }
    const auto left = LoadUnaligned<Float>(left_source);
    const auto right = LoadUnaligned<Float>(right_source);
    StoreUnaligned<Float>(output.bytes.data(),
                          Lsx4::Translation::ApplyFloatingBinary(
                              left, right, operation));
}
}

[[gnu::always_inline]] static inline void SemanticKernelComputeScalarFloating(void* dst, const void* lhs_old_dst, const void* rhs, const ScalarArithOp op,
                  const bool operate_double){
    const std::array<const void*, 2> sources{lhs_old_dst, rhs};
    if (dst == nullptr || std::ranges::any_of(
                              sources, [](const void* source) { return source == nullptr; })) {
        return;
    }
    auto result = SemanticVectorImage::Capture(sources.front(), 16);
    if (operate_double) {
        EvaluateScalarFloatingLane<double, std::uint64_t>(result, sources[0], sources[1], op);
    } else {
        EvaluateScalarFloatingLane<float, std::uint32_t>(result, sources[0], sources[1], op);
    }
    result.Publish(dst, kSemanticVectorBytes);
}

