        const std::uint64_t direct_backward_multi_jmp_consumer_rip =
            reinterpret_cast<std::uint64_t>(
                outbound_edge_code.data() + kDirectBackwardMultiJmpConsumerOffset);
        RetiringTranslationRuntime direct_backend;
