                    WriteGuestGpr64(state, LsxGpr::Rax, old_rax);
                    WriteGuestGpr64(state, LsxGpr::Rcx,
                             kUpperPoison | initial_ecx);
                    WriteGuestGpr64(state, LsxGpr::Rdx, kAuxCanaryB);
                    WriteGuestGpr64(state, LsxGpr::R15, r15);
